import React from 'react';

const OficinaBandeiraIslandia = () => {
    return (
        <div style={{ width: '300px', height: '200px', position: 'relative', backgroundColor: '#0033A0' }}>
            <div style={{ width: '100%', height: '20%', backgroundColor: '#FFFFFF', position: 'absolute', top: '40%' }}></div>
            <div style={{ width: '20%', height: '100%', backgroundColor: '#FFFFFF', position: 'absolute', left: '40%' }}></div>
            <div style={{ width: '100%', height: '10%', backgroundColor: '#C8102E', position: 'absolute', top: '45%' }}></div>
            <div style={{ width: '10%', height: '100%', backgroundColor: '#C8102E', position: 'absolute', left: '45%' }}></div>
        </div>
    );
};

export default OficinaBandeiraIslandia;
